package dev.unbox.unpvp;
import com.google.gson.*;
import net.minecraft.client.Minecraft;
import net.minecraft.util.ResourceLocation;
import java.nio.file.*;
import java.security.MessageDigest;
/** Same launcher library and account/digest checks as modern; disk decoding stays off render thread. */
public final class LocalSkin {
 static JsonObject library=new JsonObject();static String message="",pending="";private static long checked,pendingAt;private static boolean loading;private static String signature="";private static ResourceLocation texture;private static String model="default";
 public static ResourceLocation texture(){return texture;}public static String model(){return model;}
 static void tick(){long now=System.currentTimeMillis();if(!pending.isEmpty()&&now-pendingAt>20000){pending="";message="Launcher did not respond. Please retry.";}if(now-checked<1000||loading)return;checked=now;loading=true;SocialBridge.background(()->{try{JsonObject v=SocialBridge.read("unbox-skin-library.json"),ack=SocialBridge.read("unbox-skin-ack.json");Minecraft mc=Minecraft.getMinecraft();boolean own=SocialBridge.text(v,"accountUuid").replace("-","").equals(mc.getSession().getProfile().getId().toString().replace("-",""));if(!own)v=new JsonObject();final JsonObject value=v;String next=SocialBridge.text(v,"sequence")+String.valueOf(v.get("active"));java.awt.image.BufferedImage image=null;String type="default";if(!next.equals(signature)&&v.has("active")&&v.get("active").isJsonObject()){JsonObject a=v.getAsJsonObject("active");Path p=SocialBridge.root().resolve("unbox-local-skin.png");if(Files.size(p)<=1048576){byte[] b=Files.readAllBytes(p);if(b.length>=24&&java.nio.ByteBuffer.wrap(b).getInt(16)==64&&java.nio.ByteBuffer.wrap(b).getInt(20)==64&&PrivateLogin.hex(MessageDigest.getInstance("SHA-256").digest(b)).equals(SocialBridge.text(a,"sha256"))){image=javax.imageio.ImageIO.read(new java.io.ByteArrayInputStream(b));type=SocialBridge.text(a,"model").equals("slim")?"slim":"default";}}}final java.awt.image.BufferedImage decoded=image;final String skinType=type;SocialBridge.main(()->{library=value;if(!pending.isEmpty()&&pending.equals(SocialBridge.text(ack,"requestId"))){pending="";message=SocialBridge.flag(ack,"ok")?"Skin applied":SocialBridge.text(ack,"error");}if(!next.equals(signature)){signature=next;if(texture!=null)mc.getTextureManager().deleteTexture(texture);texture=decoded==null?null:mc.getTextureManager().getDynamicTextureLocation("unbox-local-skin",new net.minecraft.client.renderer.texture.DynamicTexture(decoded));model=skinType;}});}catch(Exception ignored){}finally{loading=false;}});}
 static void apply(String id,String model){if(!pending.isEmpty())return;String owner=SocialBridge.text(library,"accountId");if(owner.isEmpty()){message="Keep the launcher open and choose an account";return;}JsonObject c=new JsonObject();pending=java.util.UUID.randomUUID().toString();pendingAt=System.currentTimeMillis();c.addProperty("requestId",pending);c.addProperty("accountId",owner);c.addProperty("id",id);c.addProperty("at",pendingAt);if(model!=null)c.addProperty("model",model);message="Applying through launcher…";SocialBridge.background(()->{try{SocialBridge.write("unbox-skin-command.json",c);}catch(Exception e){SocialBridge.main(()->{pending="";message="Could not contact launcher";});}});}
}
